function validate([students, mentors]) {
  const m = students.length;
  if (m < 1 || m > 8) return 'students needs 1 to 8 rows.';
  if (mentors.length !== m) return 'mentors needs as many rows as students.';
  const n = students[0].length;
  if (n < 1 || n > 8) return 'Each row needs 1 to 8 answers.';
  for (const row of [...students, ...mentors]) {
    if (row.length !== n) return 'Every row needs the same number of answers.';
    if (row.some(v => v !== 0 && v !== 1)) return 'Every answer is 0 or 1.';
  }
  return null;
}

