function maxCompatibilitySum(students, mentors) {
  const m = students.length;
  const score = Array.from({ length: m }, () => new Array(m).fill(0));
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < m; j++) {
      for (let k = 0; k < students[i].length; k++) {
        if (students[i][k] === mentors[j][k]) {
          score[i][j]++;
        }
      }
    }
  }
  const full = 1 << m;
  const dp = new Array(full).fill(0);
  const bits = new Array(full).fill(0);
  for (let mask = 0; mask < full; mask++) {
    bits[mask] = bits[mask >> 1] + (mask & 1);
    const student = bits[mask];
    if (student === m) {
      continue;
    }
    for (let mentor = 0; mentor < m; mentor++) {
      if (mask & (1 << mentor)) {
        continue;
      }
      const next = mask | (1 << mentor);
      dp[next] = Math.max(dp[next], dp[mask] + score[student][mentor]);
    }
  }
  return dp[full - 1];
}

