function maxCompatibilitySum(students, mentors) {
  const m = students.length;
  const used = new Array(m).fill(false);
  const pairScore = (a, b) => a.reduce((total, answer, q) => total + (answer === b[q] ? 1 : 0), 0);
  let best = 0;
  const assign = (i, total) => {
    if (i === m) { best = Math.max(best, total); return; }
    for (let j = 0; j < m; j++) {
      if (used[j]) continue;
      used[j] = true;
      assign(i + 1, total + pairScore(students[i], mentors[j]));
      used[j] = false;
    }
  };
  assign(0, 0);
  return best;
}

