function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const m = size === 'large' ? 8 : 1 + pick(5);
  const n = size === 'large' ? 6 + pick(3) : 1 + pick(5);
  const bias = rand();
  const row = () => Array.from({ length: n }, () => (rand() < bias ? 1 : 0));
  return [Array.from({ length: m }, row), Array.from({ length: m }, row)];
}
